package com.skillswap.dao;

import com.skillswap.dto.SwapRequest;
import java.util.List;

public interface SwapRequestDAO {
    /**
     * Inserts a new swap request into the database.
     */
    boolean sendRequest(SwapRequest request);
    
    /**
     * Retrieves details about a specific request.
     */
    SwapRequest getRequestById(int requestId);
    
    /**
     * Retrieves all requests generated by a specific user.
     */
    List<SwapRequest> getSentRequests(int senderId);
    
    /**
     * Retrieves all requests aimed at a specific user.
     */
    List<SwapRequest> getReceivedRequests(int receiverId);
    
    /**
     * Used when a user accepts or rejects an incoming request.
     */
    boolean updateRequestStatus(int requestId, String status);
    
    /**
     * Checks to prevent duplicate spam requests between the same users for the same skills.
     */
    boolean checkExistingRequest(int senderId, int receiverId, int teachSkillId, int learnSkillId);
}
